import { type NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth"
import { authOptions } from "@/lib/auth"
import { createServerClient } from "@/lib/supabase"

export async function POST(request: NextRequest) {
    try {
        const session = await getServerSession(authOptions)
        if (!session?.user?.email) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
        }

        const supabase = createServerClient()
        const data = await request.json()

        // Buscar usuário e empresa
        const { data: user } = await supabase
            .from("users")
            .select("id, company_id")
            .eq("email", session.user.email)
            .single()

        if (!user?.company_id) {
            return NextResponse.json({ error: "Company not found" }, { status: 404 })
        }

        // Criar cobrança PIX
        const expiresAt = new Date()
        expiresAt.setHours(expiresAt.getHours() + 24) // Expira em 24 horas

        const { data: charge, error } = await supabase
            .from("pix_charges")
            .insert({
                company_id: user.company_id,
                created_by: user.id,
                amount: data.amount,
                description: data.description,
                payer_name: data.payerName,
                payer_document: data.payerDocument,
                payer_email: data.payerEmail,
                expires_at: expiresAt.toISOString(),
                pix_key: `pix-${Date.now()}`, // Simular chave PIX
                qr_code: `data:image/png;base64,`,
            })
            .select()
            .single()

        if (error) throw error

        return NextResponse.json({ success: true, charge })
    } catch (error) {
        console.error("Error creating charge:", error)
        return NextResponse.json({ error: "Internal server error" }, { status: 500 })
    }
}

// Atualizar o método GET para suportar filtros avançados e paginação

export async function GET(request: NextRequest) {
    try {
        const session = await getServerSession(authOptions)
        if (!session?.user?.email) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
        }

        const supabase = createServerClient()
        const { searchParams } = new URL(request.url)

        const page = Number.parseInt(searchParams.get("page") || "1")
        const limit = Number.parseInt(searchParams.get("limit") || "10")
        const status = searchParams.get("status") || ""
        const search = searchParams.get("search") || ""
        const sortBy = searchParams.get("sortBy") || "created_at"
        const sortOrder = searchParams.get("sortOrder") || "desc"

        const offset = (page - 1) * limit

        // Buscar usuário e empresa
        const { data: user } = await supabase.from("users").select("id, company_id, role").eq("email", session.user.email).single()

        if (!user?.company_id) {
            return NextResponse.json({ error: "Company not found" }, { status: 404 })
        }

        // Construir query
        let query = supabase.from("pix_charges").select("*", { count: "exact" }).eq("company_id", user.company_id)


        if (user.role !== "owner" && user.role !== 'admin') {
            query = query.eq("created_by", user.id)
        }
        // Aplicar filtros
        if (status && status !== "all") {
            query = query.eq("status", status)
        }

        if (search) {
            query = query.or(`description.ilike.%${search}%,payer_name.ilike.%${search}%,payer_email.ilike.%${search}%`)
        }

        // Aplicar ordenação
        query = query.order(sortBy, { ascending: sortOrder === "asc" })

        // Aplicar paginação
        const { data: charges, error, count } = await query.range(offset, offset + limit - 1)

        if (error) throw error

        return NextResponse.json({
            charges,
            pagination: {
                page,
                limit,
                total: count || 0,
                totalPages: Math.ceil((count || 0) / limit),
            },
        })
    } catch (error) {
        console.error("Error fetching charges:", error)
        return NextResponse.json({ error: "Internal server error" }, { status: 500 })
    }
}
